// Create a random pattern string (1..4096 bytes). Ensure NUL-termination via c_str().
std::string pat = FUZZ_PARAM_STR();
const char* cpat = pat.c_str();
// Construct the RE2 object using the const char* constructor.
re2::RE2* re = new re2::RE2(cpat);
// Record whether construction succeeded for downstream stubs.
FUZZ_SET_ATTR_INT(re, "ok", re->ok() ? 1 : 0);
FUZZ_SET_ATTR_INT(re, "captures", re->NumberOfCapturingGroups());
// Persist the object by returning it as an output.

// Destroy the RE2 object; the runtime must not use it afterwards.
delete re;
// No outputs; ownership ends here.

// ok() should be equivalent to (error_code() == NoError).
bool ok1 = re->ok();
bool ok2 = (re->error_code() == re2::RE2::NoError);
FUZZ_ASSERT(ok1 == ok2, "RE2::ok() must reflect error_code() == NoError");
// Keep the object alive for further use.

// Access the pattern string; reference is valid for the lifetime of re.
const std::string& pat = re->pattern();
// Track length for potential downstream invariants.
FUZZ_SET_ATTR_INT(re, "pattern_len", (int)pat.size());
// Persist re.

// Access human-readable error string (empty on success).
const std::string& e = re->error();
// Optionally track presence of error text.
FUZZ_SET_ATTR_INT(re, "has_error_text", e.empty() ? 0 : 1);
// Persist re.

// Read the construction error code and compare with ok().
re2::RE2::ErrorCode ec = re->error_code();
bool expected_ok = (ec == re2::RE2::NoError);
FUZZ_ASSERT(re->ok() == expected_ok, "ok() must match error_code()==NoError");
// Persist re.

// Access the error location argument string; meaningful only if not ok().
const std::string& ea = re->error_arg();
// Track whether an error argument was provided.
FUZZ_SET_ATTR_INT(re, "has_error_arg", ea.empty() ? 0 : 1);
// Persist re.

int sz = re->ProgramSize();
FUZZ_ASSERT(sz >= 0, "ProgramSize() must be non-negative");
FUZZ_SET_ATTR_INT(re, "prog_size", sz);
// Persist re.

int rsz = re->ReverseProgramSize();
FUZZ_ASSERT(rsz >= 0, "ReverseProgramSize() must be non-negative");
FUZZ_SET_ATTR_INT(re, "rprog_size", rsz);
// Persist re.

// Randomly choose whether to pass a histogram pointer or null.
unsigned mode = *FUZZ_PARAM(unsigned int);
int ret = 0;
if ((mode & 1u) == 0u) {
  // Provide a histogram vector for coverage of the write path.
  std::vector<int> hist;
  ret = re->ProgramFanout(&hist);
  // Track some info for downstream.
  FUZZ_SET_ATTR_INT(re, "prog_fanout_hist_size", (int)hist.size());
} else {
  // Exercise the null histogram path.
  ret = re->ProgramFanout(nullptr);
}
FUZZ_ASSERT(ret >= 0, "ProgramFanout() return must be non-negative");
// Persist re.

unsigned mode = *FUZZ_PARAM(unsigned int);
int ret = 0;
if ((mode & 1u) == 0u) {
  std::vector<int> hist;
  ret = re->ReverseProgramFanout(&hist);
