}
FUZZ_ASSERT(ret >= 0, "ReverseProgramFanout() return must be non-negative");
// Persist re.

// Obtain the internal Regexp pointer; do not free it, lifetime bound to re.
re2::Regexp* rx = re->Regexp();
// Store pointer attribute for potential diagnostics; not to be dereferenced elsewhere.
FUZZ_SET_ATTR_PTR(re, "regexp_ptr", (void*)rx);
// Persist re.

