}
// Persist re.

// Generate input text.
std::string text = FUZZ_PARAM_STR();
absl::string_view sv(text);

// Decide number and kinds of submatch destinations using a single random seed.
unsigned sel = *FUZZ_PARAM(unsigned int);
int n = (int)(sel % 4); // 0..3

// Prepare capture destinations that outlive the call.
int cap_i0=0, cap_i1=0, cap_i2=0;
std::string cap_s0, cap_s1, cap_s2;
absl::string_view cap_v0, cap_v1, cap_v2;

// Build an array of Arg objects and a parallel array of pointers to them,
// because the N APIs expect const Arg* const args[] (array of pointers).
re2::RE2::Arg arg_objs[3];
const re2::RE2::Arg* arg_ptrs[3];
for (int k = 0; k < n; ++k) {
  unsigned kind = (sel >> (2 + 2*k)) & 3u; // 0..3
  if (k == 0) {
    if (kind == 0) arg_objs[k] = re2::RE2::Arg(&cap_i0);
    else if (kind == 1) arg_objs[k] = re2::RE2::Arg(&cap_s0);
    else if (kind == 2) arg_objs[k] = re2::RE2::Arg(&cap_v0);
    else arg_objs[k] = re2::RE2::Arg(nullptr);
  } else if (k == 1) {
    if (kind == 0) arg_objs[k] = re2::RE2::Arg(&cap_i1);
