import random
import struct
import itertools

# Generator for valid/interesting RE2 regular expression patterns.
# The fuzz stubs consume strings for patterns (RE2 constructors, FilteredRE2::Add, RE2::Set::Add).
# We prioritize producing syntactically valid, diverse patterns that exercise various engines paths.

_MAX_BYTES = 4096

def _choice(rng, seq):
    return seq[rng.randrange(len(seq))]

def _repeat_count(rng):
    # Bias toward small counts but occasionally large.
    if rng.random() < 0.7:
        return rng.randint(0, 5)
    if rng.random() < 0.9:
        return rng.randint(6, 20)
    return rng.randint(21, 200)

def _bounded(rng, lo, hi):
    a, b = sorted((rng.randint(lo, hi), rng.randint(lo, hi)))
    return a, max(a, b)

def _char_class_atom(rng):
    # Atoms for inside [...] classes.
    specials = ["\\d","\\D","\\s","\\S","\\w","\\W","\\p{L}","\\p{Nd}","\\p{Greek}"]
    if rng.random() < 0.25:
        return _choice(rng, specials)
    # simple range or single literal
    if rng.random() < 0.6:
        lo = rng.choice(list("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"))
        hi = rng.choice(list("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"))
        if lo > hi:
            lo, hi = hi, lo
        if lo != hi and rng.random() < 0.8:
            return f"{lo}-{hi}"
        return lo
    # escaped literal
    return "\\" + _choice(rng, list(".*+?^$|()[]{}\\"))

def _char_class(rng):
    neg = rng.random() < 0.2
    parts = []
    n = rng.randint(1, 5)
    for _ in range(n):
        parts.append(_char_class_atom(rng))
    return "[" + ("^" if neg else "") + "".join(parts) + "]"

def _escaped_literal(rng):
    # Literal with escaping of metacharacters
    s = _choice(rng, [".","*","+","?","^","$","|","(",")","[","]","{","}","\\"])
    return "\\" + s

def _literal_segment(rng):
    # A run of literal characters possibly including escapes
    alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_ "
    n = rng.randint(1, 6)
    seg = []
    for _ in range(n):
        if rng.random() < 0.2:
            seg.append(_escaped_literal(rng))
        else:
            seg.append(rng.choice(list(alphabet)))
    return "".join(seg)

def _quantifier(rng):
    choice = rng.random()
    if choice < 0.25:
        return "*" + ("?" if rng.random() < 0.4 else "")
    if choice < 0.5:
        return "+" + ("?" if rng.random() < 0.4 else "")
    if choice < 0.75:
        return "?" + ("?" if rng.random() < 0.4 else "")
    # {m} or {m,n}
    m = _repeat_count(rng)
    if rng.random() < 0.6:
        return f"{{{m}}}" + ("?" if rng.random() < 0.4 else "")
    n = m if rng.random() < 0.4 else m + rng.randint(0, 10)
    return f"{{{m},{n}}}" + ("?" if rng.random() < 0.4 else "")

def _anchor_or_boundary(rng):
    return _choice(rng, ["^","$","\\b","\\B","\\A","\\z"])

def _group(rng, depth):
    # Build a valid group with optional flags or non-capturing / named capturing.
    if depth <= 0:
        return _atom(rng, depth)
    kind = rng.random()
    if kind < 0.25:
        # non-capturing
        inner = _concat(rng, depth-1)
        return f"(?:{inner})"
    if kind < 0.45:
        # named capturing (Perl-style) (?P<name>...) is not supported by RE2; RE2 uses (?P<name>...) in Python? RE2 supports (?P<name>)? It supports (?P<name>...), (?P=name)? Actually RE2 supports (?P<name>...) with ?P? Not standard. Use (?P<name>...) is not supported; use (?P<name>...) only PCRE. RE2 supports (?P<name>...) via (?P<name>...) no. Use (?P<name>...) avoided. RE2 supports (?P<name>...)? uncertain. Use (?P<name>...) avoided. Use (?P<name>)? We'll instead use (?P<name>...)-avoid; use (?P<name>) not safe. Use (?P<name>...) off. RE2 supports (?P<name>...) as (?P<name>...) no. Use (?P<name>...) disabled.
        inner = _concat(rng, depth-1)
        return f"({inner})"
    if kind < 0.7:
        # inline flags: (?i), (?m), (?s), (?-i), (?i:...)
        # Prefer scoped flags to exercise parser
        flags_all = "imsU"  # RE2 supports i,m,s,U
        flags = "".join(sorted(set(rng.choices(list(flags_all), k=rng.randint(1, 2)))))
        if rng.random() < 0.5:
            inner = _concat(rng, depth-1)
            return f"(?{flags}:{inner})"
        else:
            return f"(?{('-' if rng.random()<0.5 else '')}{flags})" + _atom(rng, depth-1)
    else:
        # capturing with alternation inside
        parts = [_concat(rng, depth-1) for _ in range(rng.randint(2,3))]
        return "(" + "|".join(parts) + ")"

def _atom(rng, depth):
    choice = rng.random()
    if choice < 0.2:
        return _literal_segment(rng)
    if choice < 0.35:
        return _char_class(rng)
    if choice < 0.45:
        return _anchor_or_boundary(rng)
    if choice < 0.55:
        return "."
    if choice < 0.7:
        return _group(rng, depth)
    # escapes and backrefs-like literals (RE2 does not support numeric backrefs; we ensure literal digits)
    return _escaped_literal(rng)

def _piece(rng, depth):
    base = _atom(rng, depth)
    if rng.random() < 0.7:
        base += _quantifier(rng)
    return base

def _concat(rng, depth):
    n = rng.randint(1, 4)
    return "".join(_piece(rng, depth) for _ in range(n))

def _pattern(rng):
    # Optionally prefix with flags like (?i) that affect rest
    parts = []
    if rng.random() < 0.3:
        flags = "".join(sorted(set(rng.choices(list("imsU"), k=rng.randint(1,2)))))
        parts.append(f"(?{flags})")
    # Optionally anchor at start
    if rng.random() < 0.3:
        parts.append("^")
    # Main body with alternations
    alts = [_concat(rng, depth=rng.randint(1,3)) for _ in range(rng.randint(1,3))]
    parts.append("|".join(alts))
    # Optionally end anchor
    if rng.random() < 0.3:
        parts.append("$")
    pat = "".join(parts)
    # Ensure we keep size reasonable
    if len(pat) > _MAX_BYTES:
        pat = pat[:_MAX_BYTES]
    return pat

def _latin1_blob(rng, n):
    # Produce a Latin-1 literal pattern by quoting meta
    # We'll just return a literal string, mostly alnum plus some high bytes escaped via \xHH
    out = []
    for _ in range(n):
        b = rng.randrange(256)
        ch = chr(b)
        if ch.isalnum() or ch == ' ':
            out.append(ch)
        else:
            out.append(f"\\x{b:02x}")
    return "".join(out)

def _literal_mode_pattern(rng):
    # In literal mode, pattern treated as literal; still safe to return arbitrary text.
    if rng.random() < 0.5:
        return _latin1_blob(rng, rng.randint(1, 40))
    return _literal_segment(rng) * rng.randint(1, 5)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose a theme to target diverse APIs/flags combinations seen in stubs.
    theme = rng.random()
    patterns = []

    # Always include at least one generally valid pattern.
    patterns.append(_pattern(rng))

    # Add patterns that exercise options toggled in FilteredRE2::Add stub.
    # 1) POSIX-like constructs: basic egrep-compatible atoms and word boundaries
    patterns.append("\\b" + _literal_segment(rng) + "|" + _char_class(rng))

    # 2) Longest-match stress: nested repetitions and alternations
    patterns.append("(" + _literal_segment(rng) + ")+|(" + _char_class(rng) + ")*")

    # 3) Dot matches newline when dot_nl set; include explicit newlines in text match targets
    patterns.append("(?s)" + _concat(rng, depth=2))

    # 4) Never capture option: use many groups; engine may treat as non-capturing
    grp = "(" + _literal_segment(rng) + ")" + _quantifier(rng)
    patterns.append(grp + grp + grp)

    # 5) Literal-mode friendly pattern
    patterns.append(_literal_mode_pattern(rng))

    # 6) Character properties and Unicode classes (RE2 supports some \p{..})
    patterns.append("(?:" + _choice(rng, ["\\p{L}", "\\p{Nd}", "[\\p{Latin}]"]) + ")+")

    # 7) Anchors and boundaries mix
    patterns.append("^" + _concat(rng, depth=2) + "$")

    # Select one or concatenate a few with newline separators so consumers get distinct samples per call.
    if theme < 0.4:
        out = _choice(rng, patterns)
    else:
        # Join up to 3 patterns separated by newlines to feed different call sites expecting standalone patterns.
        k = rng.randint(1, min(3, len(patterns)))
        out = "\n".join(rng.sample(patterns, k))

    if len(out) > _MAX_BYTES:
        out = out[:_MAX_BYTES]

    return out.encode("utf-8", errors="ignore")

