# Lines with newlines/tabs, to test anchors and dot/newline options
MULTILINE_BLOCKS = [
    "first line\nsecond line\nthird line\n",
    "start\n\nmid\tend\n",
    "a\rb\rc\n",
]

# Rewrite-like strings containing backrefs; these are valid as plain text too
REWRITE_LIKE = [
    "foo \\0 bar", "before \\1 after", "A\\2B\\9C", r"literal\\\\backslash", "\\0\\1\\2"
]

BINARY_CHUNKS = [
    bytes([0x00, 0x01, 0x02, 0x03]).decode('latin1'),
    bytes([0xFF, 0xFE, 0xFD, 0x00]).decode('latin1'),
    ("\x00" + "A"*3),
]


def _rand_choice(rng: random.Random, seq: List[str]) -> str:
    return seq[rng.randrange(len(seq))]


def _random_word(rng: random.Random, min_len=1, max_len=12) -> str:
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(ALNUM) for _ in range(n))


def _random_printable(rng: random.Random, min_len=0, max_len=32) -> str:
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(PRINTABLE) for _ in range(n))


def _join_with_seps(rng: random.Random, parts: List[str]) -> str:
    seps = [" ", ",", ";", "|", "::", "=", ":", "-", "\t"]
    out = []
    for i, p in enumerate(parts):
        out.append(p)
        if i + 1 < len(parts):
            out.append(rng.choice(seps))
    return ''.join(out)


def _make_numeric_line(rng: random.Random) -> str:
    # Build a line with several numeric representations possibly prefixed by keys
    tokens = []
    # Ensure at least one of each family sometimes
    families = [HEX_NUMBERS, OCT_NUMBERS, DEC_NUMBERS]
    rng.shuffle(families)
    for fam in families:
        tok = _rand_choice(rng, fam)
        if rng.random() < 0.6:
            tokens.append(f"n={tok}")
        else:
            tokens.append(tok)
    # Add extra random numeric tokens
    for _ in range(rng.randint(0, 3)):
        pool = rng.choice([HEX_NUMBERS, OCT_NUMBERS, DEC_NUMBERS])
        tokens.append(_rand_choice(rng, pool))
    return _join_with_seps(rng, tokens)


def _make_email_like(rng: random.Random) -> str:
    user = _random_word(rng)
    host = _random_word(rng)
    tld = rng.choice(["com", "org", "net", "io", "测试"])  # include UTF-8
    return f"{user}@{host}.{tld}"


def _make_path_like(rng: random.Random) -> str:
    parts = [ _random_word(rng, 1, 6) for _ in range(rng.randint(1, 4)) ]
    return "/" + "/".join(parts)


def _make_kv_pairs(rng: random.Random) -> str:
    n = rng.randint(1, 6)
    items = []
    for _ in range(n):
        key = _random_word(rng)
        val_type = rng.randint(0, 3)
        if val_type == 0:
            val = _random_printable(rng, 0, 8)
        elif val_type == 1:
            val = _rand_choice(rng, DEC_NUMBERS + HEX_NUMBERS + OCT_NUMBERS)
        elif val_type == 2:
            val = _make_path_like(rng)
        else:
            val = _make_email_like(rng)
        items.append(f"{key}={val}")
    return _join_with_seps(rng, items)


def _make_multiline_blob(rng: random.Random) -> str:
    parts = []
    # Ensure there are lines that may or may not match ^...$ patterns
    parts.append(_rand_choice(rng, MULTILINE_BLOCKS))
    if rng.random() < 0.7:
        parts.append(_make_email_like(rng) + "\n")
    if rng.random() < 0.7:
        parts.append(_make_path_like(rng) + "\n")
    if rng.random() < 0.7:
        parts.append(_make_numeric_line(rng) + "\n")
    return ''.join(parts)


def _make_text_piece(rng: random.Random) -> str:
    kind = rng.randint(0, 11)
    if kind == 0:
        return _random_printable(rng, 0, 32)
    if kind == 1:
        return _rand_choice(rng, HEX_NUMBERS)
    if kind == 2:
        return _rand_choice(rng, OCT_NUMBERS)
    if kind == 3:
        return _rand_choice(rng, DEC_NUMBERS)
    if kind == 4:
        return _rand_choice(rng, MIXED_FORMS)
    if kind == 5:
        return _rand_choice(rng, WORDS)
    if kind == 6:
        return _rand_choice(rng, UTF8_SAMPLES)
    if kind == 7:
        return _rand_choice(rng, REWRITE_LIKE)
    if kind == 8:
        return _make_email_like(rng)
    if kind == 9:
        return _make_kv_pairs(rng)
    if kind == 10:
        return _make_multiline_blob(rng)
    # kind 11: include some binary-like chunk embedded in text
    return _rand_choice(rng, BINARY_CHUNKS)


def _maybe_quote_meta(rng: random.Random, s: str) -> str:
    # Sometimes wrap with characters often used in regex contexts to exercise boundaries
    if rng.random() < 0.3:
        return f"^{s}$"
    if rng.random() < 0.3:
        return f"({s})"
    if rng.random() < 0.2:
        return f"[{s}]"  # note: will be just text here, still fine
    return s


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Build a composite buffer made of several pieces to increase the chance
    # that different stubs (FullMatch/PartialMatch/Consume/FindAndConsume/Rewrite)
    # see inputs that trigger varied behavior.
    pieces: List[str] = []

    # Start with a deterministic header that includes numbers in multiple radices.
    pieces.append(_make_numeric_line(rng))

    # Add several random pieces with separators encouraging tokenization.
    count = rng.randint(3, 10)
    for _ in range(count):
        p = _make_text_piece(rng)
        p = _maybe_quote_meta(rng, p)
        # Insert common separators including newlines
        sep = rng.choice([" ", "\n", "\t", ",", ";", "|"])
        pieces.append(sep)
        pieces.append(p)

    # Optionally append a rewrite-like tail to be reused as rewrite strings by stubs.
    if rng.random() < 0.7:
        pieces.append("\n")
        pieces.append(_rand_choice(rng, REWRITE_LIKE))

    # Optionally append extra UTF-8 and binary fragments.
    if rng.random() < 0.6:
        pieces.append("\n")
        pieces.append(_rand_choice(rng, UTF8_SAMPLES))
    if rng.random() < 0.4:
        pieces.append("\n")
        pieces.append(_rand_choice(rng, BINARY_CHUNKS))

    data = ''.join(pieces)

    # Bound the size to <= 4096 bytes, trimming at code point boundaries is fine since Python strings are Unicode
    # but we will encode as UTF-8/latin1-safe by choosing latin1 to preserve any 0x00..0xFF chars used above.
    if len(data.encode('latin1', errors='ignore')) > 4096:
        # Trim string length to fit roughly; do a simple slice
        data = data[:3000]

    # Encode as latin1 to preserve raw byte values we constructed, including NULs and 0xFF.
    return data.encode('latin1', errors='ignore')

import random
import string
from typing import List

def _rand_choice(r: random.Random, items: List[str]) -> str:
    return items[r.randrange(len(items))]

# Build a rewrite pattern covering RE2 features: \\0..\\9, literal text, escaped backslashes.
# The fuzz stubs feed this into functions expecting a rewrite pattern, and also as generic strings.
# We therefore keep it valid (or at least commonly valid), varied, and within 4096 bytes.

def _gen_literal(r: random.Random) -> str:
    # Mix of words, punctuation (that are safe literals in rewrite), and unicode.
    words = [
        "alpha", "beta", "gamma", "delta", "epsilon", "foo", "bar", "baz",
        "quick", "brown", "fox", "jumps", "over", "lazy", "dog",
    ]
    punct = [" ", "-", "_", ".", ",", ":", ";", "!", "?", "/", "@", "#"]
    # Some Unicode that is valid in UTF-8 contexts
    uni = ["π", "λ", "汉", "字", "á", "ç", "ñ", "€", "✓"]
    parts = []
    n = r.randint(1, 4)
    for _ in range(n):
        choice = r.random()
        if choice < 0.6:
            parts.append(_rand_choice(r, words))
        elif choice < 0.85:
            parts.append(_rand_choice(r, punct))
        else:
            parts.append(_rand_choice(r, uni))
    return "".join(parts)

def _gen_backref(r: random.Random, max_index: int) -> str:
    # Generate a valid backreference: \\0..\\9 within allowed range.
    # MaxSubmatch treats highest index referenced; re2 supports up to \\9 in rewrite.
    i = r.randint(0, min(9, max_index))
    return "\\" + str(i)

def _gen_escaped_backslash() -> str:
    # Literal backslash in rewrite is \\\\ (i.e., two characters: backslash+backslash)
    return "\\\\"

def _gen_piece(r: random.Random, max_ref: int) -> str:
    t = r.random()
    if t < 0.5:
        return _gen_literal(r)
    elif t < 0.8:
        return _gen_backref(r, max_ref)
    else:
        # Occasionally an escaped backslash or a mix
        if r.random() < 0.5:
            return _gen_escaped_backslash()
        # Combine an escaped backslash with a literal to test adjacency handling
        return _gen_escaped_backslash() + _gen_literal(r)

def _wrap_with_context(r: random.Random, core: str) -> str:
    # Surround with anchors-like text that is just literal in rewrite
    prefixes = ["", "start:", "BEGIN-", "pre:", "[" , "{"]
    suffixes = ["", ":end", "-END", ":post", "]", "}"]
    return _rand_choice(r, prefixes) + core + _rand_choice(r, suffixes)


def _generate_rewrite(r: random.Random) -> str:
    # Decide on an expected maximum capture index to reference.
    # We bias towards referencing only a few captures but sometimes go up to 9.
    max_ref = 9 if r.random() < 0.3 else r.randint(1, 4)

    # Build segments including backrefs, literals, and escaped backslashes.
    segs: List[str] = []
    # Ensure we exercise \\0 sometimes (whole match)
    if r.random() < 0.7:
        segs.append("\\0")
    # Ensure at least one non-zero backref is included if max_ref >=1
    if max_ref >= 1 and r.random() < 0.8:
        segs.append(_gen_backref(r, max_ref))

    # Add a number of random pieces
    count = r.randint(3, 12)
    for _ in range(count):
        segs.append(_gen_piece(r, max_ref))

    # Optionally interleave separators that are literal in rewrite (e.g., hyphen, space)
    seps = ["-", " ", "::", "|", "/", "_"]
    s = []
    for i, p in enumerate(segs):
        if i > 0 and r.random() < 0.5:
            s.append(_rand_choice(r, seps))
        s.append(p)

    # Optionally wrap with some surrounding literal context
    rw = _wrap_with_context(r, "".join(s))

    # Trim to max length to keep total under 4096; aim smaller for multiple FUZZ_PARAM_STR uses.
    return rw[:1024]


def _maybe_filename_payload(r: random.Random) -> bytes:
    # Some fuzz stubs may use FUZZ_PARAM_FILENAME with the same buffer. Provide content that
    # looks like file data but is still a valid rewrite string if used as string.
    # We include lines each being a rewrite pattern so either path is fine.
    lines = []
    nlines = r.randint(1, 5)
    for _ in range(nlines):
        lines.append(_generate_rewrite(r))
    return ("\n".join(lines)).encode("utf-8", errors="ignore")


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Choose a strategy:
    # - Single rewrite pattern (most common)
    # - Concatenate multiple rewrite patterns separated by newlines
    # - A small file-like payload with multiple lines
    mode = r.random()
    if mode < 0.6:
        rw = _generate_rewrite(r)
        return rw.encode("utf-8", errors="ignore")
    elif mode < 0.9:
        parts = [_generate_rewrite(r) for _ in range(r.randint(2, 6))]
        data = "\n".join(parts)
        return data[:2048].encode("utf-8", errors="ignore")
    else:
        blob = _maybe_filename_payload(r)
        return blob[:4096]
